const isSimplePower = (x, n) => {
    if (n === 1) {
        return x === 1;
    }
    if (n <= 0 || x <= 0) {
        return false;
    }
    let value = 1;
    while (value < x) {
        value *= n;
    }
    return value === x;
}

def monotonic(l: list) -> bool:
    if len(l) < 2:
        return True

    is_increasing = True
    is_decreasing = True

    for i in range(1, len(l)):
        if l[i] > l[i - 1]:
            is_increasing = True
        elif l[i] < l[i - 1]:
            is_decreasing = True
        else:
            is_increasing = False
            is_decreasing = False

        if not (is_increasing or is_decreasing):
            return False

    return is_increasing or is_decreasing

# Test cases
print(monotonic([1, 2, 4, 20]))  # True
print(monotonic([1, 20, 4, 10]))  # False
print(monotonic([4, 1, 0, -10]))  # True

