vector<vector<int>> get_row(vector<vector<int>> lst, int x){
    vector<vector<int>> result;
    for (int i = 0; i < lst.size(); ++i) {
        vector<int> row_coords;
        for (int j = 0; j < lst[i].size(); ++j) {
            if (lst[i][j] == x) {
                row_coords.push_back(j);
            }
        }
        // Sort the found column indices in descending order
        sort(row_coords.rbegin(), row_coords.rend());
        for (int col : row_coords) {
            result.push_back({i, col});
        }
    }
    return result;
}

public int modp(int n, int p) {
    long result = 1;
    long base = 2;
    while (n > 0) {
        if (n % 2 == 1) {
            result = (result * base) % p;
        }
        base = (base * base) % p;
        n /= 2;
    }
    return (int) result;
}

