function moveOneBall(arr) {
    /**
     * Determines if it is possible to get an array sorted in non-decreasing order by performing right shift operations.
     * 
     * @param {number[]} arr - The input array of integers.
     * @returns {boolean} True if it is possible to get a non-decreasing order, false otherwise.
     */
    if (arr.length === 0) {
        return true;
    }
    let max = Math.max(...arr);
    let maxIndex = arr.indexOf(max);
    let isPossible = true;
    for (let i = maxIndex + 1; i < arr.length; i++) {
        if (arr[i] < max) {
            isPossible = false;
            break;
        }
    }
    return isPossible;
}

