```javascript
/**
 * Given two positive integers a and b, return the even digits between a and b, in ascending order.
 * 
 * @param {number} a The start of the range (inclusive).
 * @param {number} b The end of the range (inclusive).
 * @returns {number[]} An array of even digits between a and b.
 * 
 * Example:
 * generateIntegers(2, 8) => [2, 4, 6, 8]
 * generateIntegers(8, 2) => [2, 4, 6, 8]
 * generateIntegers(10, 14) => []
 */
const generateIntegers = (a, b) => {
  const result = [];
  for (let i = Math.min(a, b); i <= Math.max(a, b); i++) {
    if (i % 2 === 0) {
      result.push(i);
    }
  }
  return result;
}
```

