 * 
 * @param {number[]} numbers - The list of numbers to check.
 * @param {number} threshold - The minimum distance between two numbers to be considered close.
 * @returns {boolean} True if any two numbers are closer than the threshold, false otherwise.
 */
const hasCloseElements = (numbers, threshold) => {
  numbers.sort((a, b) => a - b);
  for (let i = 0; i < numbers.length - 1; i++) {
    if (numbers[i + 1] - numbers[i] < threshold) {
      return true;
    }
  }
  return false;
};
