public String getClosestVowel(String word) {
    String vowels = "aeiouAEIOU";
    int vowelIndex = -1;
    int consonantIndex = -1;
    int consonantCount = 0;

    for (int i = 1; i < word.length() - 1; i++) {
        if (vowels.contains(String.valueOf(word.charAt(i)))) {
            vowelIndex = i;
        } else if (Character.isLetter(word.charAt(i))) {
            consonantCount++;
        }
    }

    if (consonantCount > 0) {
        consonantIndex = word.length() - 2;
        while (consonantIndex >= 0 && !vowels.contains(String.valueOf(word.charAt(consonantIndex)))) {
            consonantIndex--;
        }
        if (consonantIndex >= 0) {
            return word.charAt(consonantIndex + 1);
        }
    }

    return "";
}

