// brackets is a string of "(" and ")".
// return true if every opening bracket has a corresponding closing bracket.
// 
// >>> CorrectBracketing("(")
// false
// >>> CorrectBracketing("()")
// true
// >>> CorrectBracketing("(()())")
// true
// >>> CorrectBracketing(")(()")
// false
func CorrectBracketing(brackets string) bool {
    count := 0
    for _, ch := range brackets {
        if ch == '(' {
            count++
        } else if ch == ')' {
            count--
            if count < 0 {
                return false
            }
        }
    }
    return count == 0
}

