#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <cmath>
using namespace std;

int evaluate_expression(const vector<string>& operators, const vector<int>& operands) {
    string expression;
    for (size_t i = 0; i < operators.size(); ++i) {
        expression += to_string(operands[i]);
        expression += " ";
        expression += operators[i];
        expression += " ";
    }
    expression += to_string(operands.back());

    // Use a simple evaluation strategy (RPN)
    istringstream iss(expression);
    string op1, op2, result;
    int num1, num2;
    while (iss >> num1) {
        if (iss.peek() == ' ') {
            iss >> op1;
        } else {
            break;
        }
    }
    while (iss >> num2) {
        if (iss.peek() == ' ') {
            iss >> op2;
        } else {
            break;
        }
    }
    if (op1 == "+") {
        return num1 + num2;
    } else if (op1 == "-") {
        return num1 - num2;
    } else if (op1 == "*") {
        return num1 * num2;
    } else if (op1 == "/") {
        return num1 / num2;
    } else if (op1 == "**") {
        return pow(num1, num2);
    } else {
        return 0; // Invalid operator
    }
}

int do_algebra(vector<string> operators, vector<int> operands) {
    return evaluate_expression(operators, operands);
}
