import java.util.Scanner;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Solution {

    /**
    You are given a word. Your task is to find the closest vowel that stands between
    two consonants from the right side of the word (case sensitive).

    Vowels in the beginning and ending doesn't count. Return empty string if you didn't
    find any vowel met the above condition.

    You may assume that the given string contains English letter only.

    Example:
    getClosestVowel("yogurt") ==> "u"
    getClosestVowel("FULL") ==> "U"
    getClosestVowel("quick") ==> ""
    getClosestVowel("ab") ==> ""
     */
    public String getClosestVowel(String word) {
        String vowels = "aeiouAEIOU";
        Pattern pattern = Pattern.compile("[^" + vowels + "]");
        Matcher matcher = pattern.matcher(word);
        int start = word.length();
        int end = -1;

        for (int i = word.length() - 1; i >= 0; i--) {
            if (matcher.find(i)) {
                start = i;
                break;
            }
        }

        for (int i = start - 1; i >= 0; i--) {
            if (matcher.find(i) && vowels.indexOf(word.charAt(i)) != -1) {
                end = i;
                break;
            }
        }

        if (end != -1) {
            return word.substring(end, start);
        }
        return "";
    }
}

const fileNameCheck = (file_name) => {
  // Check if there is exactly one dot
  const parts = file_name.split('.');
  if (parts.length !== 2) return 'No';

  const [name, ext] = parts;

  // Check if name part is not empty and starts with a letter
  if (!name || !/^[A-Za-z]/.test(name)) return 'No';

  // Check if extension is valid
  const validExtensions = ['txt', 'exe', 'dll'];
  if (!validExtensions.includes(ext)) return 'No';

  // Count digits in the entire file name
  const digitCount = (file_name.match(/\d/g) || []).length;
  if (digitCount > 3) return 'No';

  return 'Yes';
};

