const parseNestedParens = (paren_string) => {
    let result = [];
    let count = 0;
    let max_count = 0;

    for (let i = 0; i < paren_string.length; i++) {
        if (paren_string[i] === '(') {
            count++;
        } else if (paren_string[i] === ')') {
            count--;
            if (count > max_count) {
                max_count = count;
            }
        }
    }

    // Add the final max count to the result
    result.push(max_count);

    return result;
};

