vector<float> rescale_to_unit(vector<float> numbers) {
    if (numbers.empty()) {
        return {}; // Return empty vector if input is empty
    }
    float min_val = numbers[0];
    float max_val = numbers[0];
    // Find min and max values
    for (float num : numbers) {
        if (num < min_val) min_val = num;
        if (num > max_val) max_val = num;
    }
    float range = max_val - min_val;
    // If all numbers are the same, return a vector of zeros
    if (range == 0.0f) {
        return vector<float>(numbers.size(), 0.0f);
    }
    vector<float> rescaled;
    rescaled.reserve(numbers.size());
    for (float num : numbers) {
        rescaled.push_back((num - min_val) / range);
    }
    return rescaled;
}

