func Factorize(n int) []int {
    factors := []int{}
    for n % 2 == 0 {
        factors = append(factors, 2)
        n /= 2
    }
    for i := 3; i <= math.Sqrt(n); i += 2 {
        for n % i == 0 {
            factors = append(factors, i)
            n /= i
        }
    }
    if n > 2 {
        factors = append(factors, n)
    }
    return factors
}

const isSimplePower = (x, n) => {
    if (n === 1) {
        return x === 1;
    }
    if (n === 0) {
        return x === 1;
    }
    if (x < 1 || n < 1) {
        return false;
    }
    let current = 1;
    while (current < x) {
        current *= n;
    }
    return current === x;
}

