Here's a JavaScript function that removes all elements that occur more than once from a list of integers while maintaining the order of the remaining elements:

```javascript
const removeDuplicates = (numbers) => {
  const seen = new Set();
  const result = [];

  for (const number of numbers) {
    if (!seen.has(number)) {
      seen.add(number);
      result.push(number);
    }
  }

  return result;
};

console.log(removeDuplicates([1, 2, 3, 2, 4])); // [1, 3, 4]
```

This function uses a `Set` to keep track of the unique elements encountered so far. It iterates through the input array and adds each element to the `Set` and the result array if it hasn't been seen before. This way, duplicate elements are effectively removed, and the order of the remaining elements is preserved.

#include<stdio.h>
#include<math.h>
#include<string>
#include<vector>
using namespace std;

vector<int> even_odd_count(int num){
    vector<int> result(2, 0); // Initialize the result vector with 0s for even and odd counts

    // Handle negative numbers by converting them to positive
    if (num < 0) {
        num = -num;
    }

    // Iterate through each digit of the number
    while (num > 0) {
        int digit = num % 10; // Get the last digit
        if (digit % 2 == 0) {
            result[0]++; // Increment even count
        } else {
            result[1]++; // Increment odd count
        }
        num /= 10; // Remove the last digit
    }

    return result;
}

int main() {
    int num1 = -12;
    int num2 = 123;

    vector<int> result1 = even_odd_count(num1);
    vector<int> result2 = even_odd_count(num2);

    printf("even_odd_count(%d) ==> {%d, %d}\n", num1, result1[0], result1[1]);
    printf("even_odd_count(%d) ==> {%d, %d}\n", num2, result2[0], result2[1]);

    return 0;
}

