class Solution {
    public List<Double> rescaleToUnit(List<Double> numbers) {
        if (numbers == null || numbers.size() < 2) {
            throw new IllegalArgumentException("Input list must contain at least two elements.");
        }

        double min = Collections.min(numbers);
        double max = Collections.max(numbers);

        if (min == max) {
            return Collections.singletonList(min);
        }

        List<Double> rescaledList = new ArrayList<>();
        for (Double num : numbers) {
            rescaledList.add((num - min) / (max - min));
        }
        return rescaledList;
    }
}
