const moveOneBall = (arr) => {
  if (arr.length === 0) return true;

  for (let i = 0; i < arr.length - 1; i++) {
    if (arr[i] > arr[i + 1]) {
      // Find the minimum element in the remaining array that is greater than the current element
      let minIndex = arr.slice(i + 1).indexOf(Math.min(...arr.slice(i + 1))) + i + 1;
      if (minIndex === arr.length) return false;

      // Swap the current element with the minimum element found
      [arr[i], arr[minIndex]] = [arr[minIndex], arr[i]];

      // Sort the remaining array to the right of the swapped element
      arr.slice(i + 1).sort((a, b) => a - b);
      return true;
    }
  }
  return true;
}

