def check_if_last_char_is_a_letter(string txt){
    if (txt.empty())
        return false;

    // Remove trailing spaces
    int i = txt.size() - 1;
    while (i >= 0 && txt[i] == ' ')
        i--;

    if (i < 0)
        return false;

    // Check if last non-space character is a letter
    if (!isalpha(txt[i]))
        return false;

    // Ensure it's not part of a word (preceded by space or start)
    if (i == 0 || txt[i - 1] == ' ')
        return true;

    return false;
}

