const parseNestedParens = (paren_string) => {
  const groups = paren_string.split(' ');
  const results = [];

  groups.forEach(group => {
    let maxDepth = 0;
    let currentDepth = 0;

    for (let char of group) {
      if (char === '(') {
        currentDepth++;
        if (currentDepth > maxDepth) {
          maxDepth = currentDepth;
        }
      } else if (char === ')') {
        currentDepth--;
      }
    }

    results.push(maxDepth);
  });

  return results;
};
