func Bf(planet1, planet2 string) []string {
    planets := []string{"Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"}
    idx1, idx2 := -1, -1
    for i, p := range planets {
        if p == planet1 {
            idx1 = i
        }
        if p == planet2 {
            idx2 = i
        }
    }
    if idx1 == -1 || idx2 == -1 {
        return []string{}
    }
    if idx1 > idx2 {
        idx1, idx2 = idx2, idx1
    }
    if idx2-idx1 <= 1 {
        return []string{}
    }
    return planets[idx1+1 : idx2]
}

