```go
package main

import (
	"fmt"
)

func isPrime(n int) bool {
	if n <= 1 {
		return false
	}
	for i := 2; i*i <= n; i++ {
		if n%i == 0 {
			return false
		}
	}
	return true
}

func XOrY(n, x, y int) int {
	if isPrime(n) {
		return x
	}
	return y
}

func main() {
	fmt.Println(XOrY(7, 34, 12)) // 34
	fmt.Println(XOrY(15, 8, 5)) // 5
}
```

This program defines a helper function `isPrime` that checks if a given number is prime. The `XOrY` function then uses this helper function to determine whether to return `x` or `y`. The `main` function demonstrates the usage of `XOrY` with the provided examples.

func Factorize(n int) []int {
    factors := []int{}
    for n % 2 == 0 {
        factors = append(factors, 2)
        n /= 2
    }
    for i := 3; i <= math.Sqrt(n); i += 2 {
        for n % i == 0 {
            factors = append(factors, i)
            n /= i
        }
    }
    if n > 2 {
        factors = append(factors, n)
    }
    return factors
}

func Monotonic(l []int) bool {
    isIncreasing := true
    prev := l[0]

    for i := 1; i < len(l); i++ {
        if l[i] < prev {
            if isIncreasing {
                isIncreasing = false
            }
            if l[i] > l[i-1] {
                return false
            }
        } else if l[i] > prev {
            prev = l[i]
        }
    }

    return isIncreasing
}

def HexKey(num string) int {
    // Define the set of prime hexadecimal digits
    primeHexDigits := map[rune]bool{
        '2': true,
        '3': true,
        '5': true,
        '7': true,
        'B': true,
        'D': true,
    }

    count := 0
    for _, ch := range num {
        if primeHexDigits[ch] {
            count++
        }
    }
    return count
}

