    bool found = false;

    for (int i = 1; i < n - 1; i++) {
        if (vowels.find(word[i]) != string::npos) {
            vowelIndex = i;
            found = true;
            break;
        }
    }

    if (found) {
        return word[vowelIndex];
    } else {
        return "";
    }
}

