    let min = Infinity;
    let max = -Infinity;
    let minIndex = -1;
    let maxIndex = -1;

    for (let i = 0; i < lst.length; i++) {
        if (lst[i] <= min) {
            min = lst[i];
            minIndex = i;
        }
        if (lst[i] >= max) {
            max = lst[i];
            maxIndex = i;
        }
    }

    result.push(min);
    result.push(max);

    let remaining = lst.filter(i => i !== min && i !== max);
    while (remaining.length > 0) {
        if (minIndex > maxIndex) {
            min = Infinity;
            for (let i = 0; i < remaining.length; i++) {
                if (remaining[i] <= min) {
                    min = remaining[i];
                    minIndex = i;
                }
            }
        } else {
            max = -Infinity;
            for (let i = 0; i < remaining.length; i++) {
                if (remaining[i] >= max) {
                    max = remaining[i];
                    maxIndex = i;
                }
            }
        }
        result.push(min);
        result.push(max);
        remaining = remaining.filter(i => i !== min && i !== max);
    }

    return result;
}
