Input: /*
Create a function that takes a value (string) representing a number
and returns the closest integer to it. If the number is equidistant
from two integers, round it away from zero.

Examples
>>> closest_integer("10")
10
>>> closest_integer("15.3")
15

Note:
Rounding away from zero means that if the given number is equidistant
from two integers, the one you should return is the one that is the
farthest from zero. For example closest_integer("14.5") should
return 15 and closest_integer("-14.5") should return -15.
*/
#include<stdio.h>
#include<math.h>
#include<string>
using namespace std;

int closest_integer(string value){
    // Convert string to double
    double num = stod(value);
    // Calculate floor and ceil
    double floor_num = floor(num);
    double ceil_num = ceil(num);
    // Determine the distance to floor and ceil
    double dist_floor = fabs(num - floor_num);
    double dist_ceil = fabs(ceil_num - num);
    // If the number is exactly halfway between two integers
    if (dist_floor == dist_ceil) {
        // Round away from zero
        if (num > 0) {
            return (int)ceil_num;
        } else {
            return (int)floor_num;
        }
    }
    // Otherwise, return the nearest integer
    return (int)((dist_floor < dist_ceil) ? floor_num : ceil_num);
}

