func Bf(planet1, planet2 string) []string {
    planets := [...]string{
        "Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune",
    }
    planetOrder := [...]string{
        "Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune",
    }

    p1idx := -1
    p2idx := -1

    for i, planet := range planetOrder {
        if planet == planet1 { p1idx = i }
        if planet == planet2 { p2idx = i }
    }

    if p1idx == -1 || p2idx == -1 {
        return []string{}
    }

    if p1idx > p2idx {
        p1idx, p2idx = p2idx, p1idx
    }

    includedPlanets := make([]string, 0)
    for i := p1idx + 1; i < p2idx; i++ {
        includedPlanets = append(includedPlanets, planetOrder[i])
    }

    return includedPlanets
}
