To solve this problem, we can iterate through the vector from both ends, comparing the elements at the same position. If they are not equal, we increment a counter. The counter will give us the minimum number of changes required to make the vector palindromic.

Here's the complete code:

```cpp
#include <iostream>
#include <vector>
using namespace std;

int smallest_change(vector<int> arr) {
    int n = arr.size();
    int count = 0;

    for (int i = 0; i < n / 2; i++) {
        if (arr[i] != arr[n - 1 - i]) {
            count++;
        }
    }

    return count;
}

int main() {
    vector<int> arr1 = {1, 2, 3, 5, 4, 7, 9, 6};
    vector<int> arr2 = {1, 2, 3, 4, 3, 2, 2};
    vector<int> arr3 = {1, 2, 3, 2, 1};

    cout << "smallest_change({" << arr1[0] << ", " << arr1[1] << ", " << arr1[2] << ", " << arr1[3] << ", " << arr1[4] << ", " << arr1[5] << ", " << arr1[6] << ", " << arr1[7] << "}) == " << smallest_change(arr1) << endl;
    cout << "smallest_change({" << arr2[0] << ", " << arr2[1] << ", " << arr2[2] << ", " << arr2[3] << ", " << arr2[4] << ", " << arr2[5] << ", " << arr2[6] << "}) == " << smallest_change(arr2) << endl;
    cout << "smallest_change({" << arr3[0] << ", " << arr3[1] << ", " << arr3[2] << ", " << arr3[3] << ", " << arr3[4] << "}) == " << smallest_change(arr3) << endl;

    return 0;
}
```

This code defines the `smallest_change` function that takes a vector of integers as input and returns the minimum number of changes required to make the vector palindromic. It then tests the function with three example vectors and prints the results.

When you run this code, you will get the following output:

```
smallest_change({1, 2, 3, 5, 4, 7, 9, 6}) == 4
