    let binarySum = "";
    while (N > 0) {
        sum += N % 2;
        binarySum = N % 2 + binarySum;
        N = Math.floor(N / 2);
    }
    return binarySum;
};

const evenOddCount = (num) => {
  if (num < 0) {
    num = -num;
  }

  let evenCount = 0;
  let oddCount = 0;

  while (num > 0) {
    const digit = num % 10;
    if (digit % 2 === 0) {
      evenCount++;
    } else {
      oddCount++;
    }
    num = Math.floor(num / 10);
  }

  return [evenCount, oddCount];
};

console.log(evenOddCount(-12)); // [1, 1]
console.log(evenOddCount(123)); // [1, 2]

