func XOrY(n, x, y int) int {
    if isPrime(n) {
        return x
    }
    return y
}

// Helper function to check if a number is prime
func isPrime(n int) bool {
    if n <= 1 {
        return false
    }
    for i := 2; i*i <= n; i++ {
        if n%i == 0 {
            return false
        }
    }
    return true
}
